17	// 在 stations + road_nodes 混合节点集合中按 id 查找坐标。
18	std::optional<std::pair<double, double>> FindNodeCoord(
19	    const catalog::StationCatalog& catalog, const std::string& id) {
20	  for (const auto& station : catalog.stations) {
21	    if (station.id == id) {
22	      return std::pair<double, double>{station.x, station.y};
23	    }
24	  }
25	  for (const auto& road_node : catalog.road_nodes) {
26	    if (road_node.id == id) {
27	      return std::pair<double, double>{road_node.x, road_node.y};
28	    }
29	  }
30	  return std::nullopt;
31	}
