33	// 追加折线点并去除相邻边接缝处的重复点（零长度段会破坏等距插值）。
34	void AppendPoint(Polyline& polyline, double x, double y) {
35	  if (!polyline.empty() &&
36	      std::hypot(polyline.back().first - x, polyline.back().second - y) <
37	          kJoinEps) {
38	    return;
39	  }
40	  polyline.emplace_back(x, y);
41	}
42	
43	// 沿折线按弧长 d 插值位姿（d ∈ [0, total]），航向取所在段方向。
44	Pose2D InterpolateAt(const Polyline& polyline,
45	                     const std::vector<double>& cumulative, double d,
46	                     bool final_point,
47	                     const std::optional<double>& final_theta) {
48	  const double total = cumulative.back();
49	  d = std::clamp(d, 0.0, total);
50	
51	  // 定位所在段：最后一个满足 cumulative[i] <= d 的段 [i, i+1]。
52	  std::size_t index = 0;
53	  for (std::size_t i = 0; i + 1 < cumulative.size(); ++i) {
54	    if (cumulative[i] <= d + kJoinEps) {
55	      index = i;
56	    } else {
57	      break;
58	    }
59	  }
60	  const auto& a = polyline[index];
61	  const auto& b = polyline[index + 1];
62	  const double seg_len = cumulative[index + 1] - cumulative[index];
63	  const double ratio = seg_len > kJoinEps ? (d - cumulative[index]) / seg_len : 0.0;
64	
65	  Pose2D pose;
66	  pose.x = a.first + ratio * (b.first - a.first);
67	  pose.y = a.second + ratio * (b.second - a.second);
68	  pose.theta = std::atan2(b.second - a.second, b.first - a.first);
69	  if (final_point && final_theta.has_value()) {
70	    pose.theta = *final_theta;
71	  }
72	  return pose;
73	}
74	
75	// 等距插值重采样：总长 L、步长 step，取 num_steps = ceil(L / step) 段，
76	// 采样间距 L / num_steps ≤ step（与 MockLinearPlanner 一致），
77	// 首路点严格为折线起点、末路点严格为折线终点。
78	std::vector<Pose2D> ResamplePolyline(
79	    const Polyline& polyline, double step_size,
80	    const std::optional<double>& first_theta = std::nullopt,
81	    const std::optional<double>& final_theta = std::nullopt) {
82	  std::vector<Pose2D> path;
83	  if (polyline.empty()) {
84	    return path;
85	  }
86	
87	  std::vector<double> cumulative(polyline.size(), 0.0);
88	  for (std::size_t i = 1; i < polyline.size(); ++i) {
89	    cumulative[i] =
90	        cumulative[i - 1] +
91	        std::hypot(polyline[i].first - polyline[i - 1].first,
92	                   polyline[i].second - polyline[i - 1].second);
93	  }
94	  const double total = cumulative.back();
95	
96	  if (total <= kJoinEps || polyline.size() == 1) {
97	    Pose2D pose;
98	    pose.x = polyline.front().first;
99	    pose.y = polyline.front().second;
100	    pose.theta = first_theta.value_or(final_theta.value_or(0.0));
101	    path.push_back(pose);
102	    return path;
103	  }
104	
105	  const int num_steps =
106	      std::max(1, static_cast<int>(std::ceil(total / step_size)));
107	  path.reserve(static_cast<std::size_t>(num_steps) + 1);
108	  for (int i = 0; i <= num_steps; ++i) {
109	    const double d = total * static_cast<double>(i) / num_steps;
110	    const bool first = (i == 0);
111	    const bool last = (i == num_steps);
112	    Pose2D pose = InterpolateAt(polyline, cumulative, d, last, final_theta);
113	    if (first && first_theta.has_value()) {
114	      pose.theta = *first_theta;
115	    }
116	    path.push_back(pose);
117	  }
118	  return path;
119	}
120	
121	// 在混合节点集合中查找离 (x, y) 最近的节点 id 与其坐标。
122	struct NearestNode {
123	  std::string id;
124	  double x = 0.0;
125	  double y = 0.0;
126	};
127	
128	std::optional<NearestNode> FindNearestNode(const catalog::StationCatalog& catalog,
129	                                           double x, double y) {
130	  std::optional<NearestNode> best;
131	  double best_dist = std::numeric_limits<double>::infinity();
132	  const auto consider = [&](const std::string& id, double nx, double ny) {
133	    const double dist = std::hypot(nx - x, ny - y);
134	    if (dist < best_dist) {
135	      best_dist = dist;
136	      best = NearestNode{id, nx, ny};
137	    }
138	  };
139	  for (const auto& station : catalog.stations) {
140	    consider(station.id, station.x, station.y);
141	  }
142	  for (const auto& road_node : catalog.road_nodes) {
143	    consider(road_node.id, road_node.x, road_node.y);
144	  }
145	  return best;
146	}
147	
148	// 查找路径相邻节点对 (from, to) 对应的边折线：
149	// 正向直接使用 edge.polyline；反向（双向边）使用其反转版本；
150	// 边缺失或折线不足 2 点时退化为两节点坐标间的直线。
151	Polyline EdgePolylineFor(const catalog::StationCatalog& catalog,
152	                         const std::string& from, const std::string& to,
153	                         const std::pair<double, double>& from_coord,
154	                         const std::pair<double, double>& to_coord) {
155	  const catalog::CatalogStationEdge* matched = nullptr;
156	  bool reverse = false;
157	  for (const auto& edge : catalog.edges) {
158	    if (!edge.enabled) {
159	      continue;
160	    }
161	    if (edge.from == from && edge.to == to) {
162	      matched = &edge;
163	      reverse = false;
164	      break;
165	    }
166	    if (edge.bidirectional && edge.to == from && edge.from == to) {
167	      matched = &edge;
168	      reverse = true;
169	      break;
170	    }
171	  }
172	
173	  Polyline segment;
174	  if (matched != nullptr && matched->polyline.size() >= 2) {
175	    segment.reserve(matched->polyline.size());
176	    if (reverse) {
177	      for (auto it = matched->polyline.rbegin(); it != matched->polyline.rend();
178	           ++it) {
179	        segment.push_back(*it);
180	      }
181	    } else {
182	      segment = matched->polyline;
183	    }
184	  } else {
185	    // 退化：无匹配边 / 无有效折线 -> 两点直线
186	    segment.push_back(from_coord);
187	    segment.push_back(to_coord);
188	  }
189	  return segment;
190	}
191	
192	}  // namespace
193	
194	SkeletonPlanner::SkeletonPlanner(catalog::StationCatalog catalog, Config config)
195	    : catalog_(std::move(catalog)), config_(config) {
196	  if (config_.step_size <= 0.0) {
197	    config_.step_size = 0.1;
198	  }
199	}
