205	std::vector<Pose2D> SkeletonPlanner::PlanBetweenNodes(const std::string& from_node,
206	                                                      const std::string& to_node) {
207	  const auto route = catalog::FindRoutePath(catalog_, from_node, to_node);
208	  if (!route.has_value() || route->empty()) {
209	    return {};
210	  }
211	
212	  if (route->size() == 1) {
213	    const auto coord = FindNodeCoord(catalog_, from_node);
214	    if (!coord.has_value()) {
215	      return {};
216	    }
217	    Pose2D pose;
218	    pose.x = coord->first;
219	    pose.y = coord->second;
220	    pose.theta = 0.0;
221	    return {pose};
222	  }
223	
224	  Polyline polyline;
225	  for (std::size_t i = 0; i + 1 < route->size(); ++i) {
226	    const auto from_coord = FindNodeCoord(catalog_, (*route)[i]);
227	    const auto to_coord = FindNodeCoord(catalog_, (*route)[i + 1]);
228	    if (!from_coord.has_value() || !to_coord.has_value()) {
229	      return {};  // 路径含未知节点（目录异常）：规划失败
230	    }
231	    const Polyline segment =
232	        EdgePolylineFor(catalog_, (*route)[i], (*route)[i + 1], *from_coord,
233	                        *to_coord);
234	    for (const auto& point : segment) {
235	      AppendPoint(polyline, point.first, point.second);
236	    }
237	  }
238	
239	  return ResamplePolyline(polyline, config_.step_size);
240	}
241	
242	std::vector<Pose2D> SkeletonPlanner::Plan(const Pose2D& start, const Pose2D& goal,
243	                                          const std::string& /*edge_id*/) {
244	  if (std::hypot(goal.x - start.x, goal.y - start.y) <= kJoinEps) {
245	    return {start};
246	  }
247	
248	  const auto start_node = FindNearestNode(catalog_, start.x, start.y);
249	  const auto goal_node = FindNearestNode(catalog_, goal.x, goal.y);
250	  if (!start_node.has_value() || !goal_node.has_value()) {
251	    return {};  // 空目录：无可吸附节点
252	  }
253	
254	  const auto route = catalog::FindRoutePath(catalog_, start_node->id, goal_node->id);
255	  if (!route.has_value() || route->empty()) {
256	    return {};
257	  }
258	
259	  // 拼接总折线：start 接驳段 + 各边折线 + goal 接驳段
260	  Polyline polyline;
261	  AppendPoint(polyline, start.x, start.y);
262	  if (route->size() == 1) {
263	    // 起终点吸附到同一节点
264	    AppendPoint(polyline, start_node->x, start_node->y);
265	  } else {
266	    for (std::size_t i = 0; i + 1 < route->size(); ++i) {
267	      const auto from_coord = FindNodeCoord(catalog_, (*route)[i]);
268	      const auto to_coord = FindNodeCoord(catalog_, (*route)[i + 1]);
269	      if (!from_coord.has_value() || !to_coord.has_value()) {
270	        return {};
271	      }
272	      const Polyline segment =
273	          EdgePolylineFor(catalog_, (*route)[i], (*route)[i + 1], *from_coord,
274	                          *to_coord);
275	      for (const auto& point : segment) {
276	        AppendPoint(polyline, point.first, point.second);
277	      }
278	    }
279	  }
280	  AppendPoint(polyline, goal.x, goal.y);
281	
282	  // 首路点严格为 start（含其航向），末路点严格为 goal（含其航向）
283	  return ResamplePolyline(polyline, config_.step_size, start.theta, goal.theta);
284	}
285	
286	}  // namespace amr_dispatcher_core::planning
