#include "amr_dispatcher_core/planning/skeleton_planner.hpp"
#include <cmath>
#include <cstdio>
#include <limits>

using namespace amr_dispatcher_core;
using namespace amr_dispatcher_core::planning;

catalog::StationCatalog MakeL() {
  catalog::StationCatalog c;
  catalog::Station a; a.id="A"; a.x=0; a.y=0;
  catalog::Station b; b.id="B"; b.x=5; b.y=5;
  catalog::RoadNode j; j.id="Junc"; j.x=0; j.y=5;
  c.stations = {a,b}; c.road_nodes = {j};
  auto mk=[](const char*f,const char*t,std::vector<std::pair<double,double>> p){
    catalog::CatalogStationEdge e; e.from=f; e.to=t; e.distance_m=1; e.bidirectional=true; e.enabled=true; e.polyline=std::move(p); return e;};
  c.edges.push_back(mk("A","Junc",{{0,0},{0,5}}));
  c.edges.push_back(mk("Junc","B",{{0,5},{5,5}}));
  return c;
}

int main() {
  // 1. empty catalog
  {
    SkeletonPlanner p(catalog::StationCatalog{});
    auto path = p.Plan(Pose2D{0,0,0}, Pose2D{1,1,0});
    printf("empty catalog Plan size=%zu (expect 0)\n", path.size());
    auto path2 = p.PlanBetweenNodes("A","B");
    printf("empty catalog PlanBetweenNodes size=%zu (expect 0)\n", path2.size());
    auto path3 = p.PlanBetweenNodes("A","A");
    printf("empty catalog same-id PlanBetweenNodes size=%zu (expect 0)\n", path3.size());
  }
  // 2. step_size clamping
  {
    SkeletonPlanner::Config cfg; cfg.step_size = -1.0;
    SkeletonPlanner p(MakeL(), cfg);
    auto path = p.Plan(Pose2D{0,0,0}, Pose2D{5,5,0});
    printf("step=-1 -> n=%zu first=(%.3f,%.3f) last=(%.3f,%.3f)\n", path.size(),
           path.front().x, path.front().y, path.back().x, path.back().y);
    double maxsp=0; for(size_t i=1;i<path.size();++i) maxsp=std::max(maxsp, std::hypot(path[i].x-path[i-1].x, path[i].y-path[i-1].y));
    printf("  max spacing=%.4f (expect <=0.1)\n", maxsp);
  }
  // 3. NaN step_size
  {
    SkeletonPlanner::Config cfg; cfg.step_size = std::numeric_limits<double>::quiet_NaN();
    SkeletonPlanner p(MakeL(), cfg);
    auto path = p.Plan(Pose2D{0,0,0}, Pose2D{5,5,0});
    printf("step=NaN -> n=%zu\n", path.size());
  }
  // 4. extremely small step_size (int overflow)
  {
    SkeletonPlanner::Config cfg; cfg.step_size = 1e-9;
    SkeletonPlanner p(MakeL(), cfg);
    auto path = p.Plan(Pose2D{0,0,0}, Pose2D{5,5,0});
    printf("step=1e-9 -> n=%zu (expect ~1e10 if no overflow)\n", path.size());
  }
  // 5. goal within 1e-9 of last polyline point -> endpoint guarantee?
  {
    SkeletonPlanner p(MakeL());
    Pose2D goal{5.0, 5.0+5e-10, 1.0};
    auto path = p.Plan(Pose2D{0,0,0}, goal);
    printf("goal off by 5e-10 -> last=(%.15f,%.15f) goal=(%.15f,%.15f) endtheta=%.3f goaltheta=%.3f\n",
           path.back().x, path.back().y, goal.x, goal.y, path.back().theta, goal.theta);
    printf("  endpoint matches goal? %s\n",
           (std::abs(path.back().x-goal.x)<1e-12 && std::abs(path.back().y-goal.y)<1e-12) ? "yes":"NO");
  }
  // 6. start==goal returns start with theta
  {
    SkeletonPlanner p(MakeL());
    auto path = p.Plan(Pose2D{1.5,2.5,0.7}, Pose2D{1.5,2.5,0.7});
    printf("start==goal -> n=%zu theta=%.3f\n", path.size(), path.empty()?-1:path[0].theta);
  }
  // 7. seam mismatch 1e-6 between adjacent edge polylines
  {
    catalog::StationCatalog c = MakeL();
    c.edges[1].polyline = {{0.0+1e-6, 5.0}, {5,5}};
    SkeletonPlanner p(std::move(c));
    auto path = p.PlanBetweenNodes("A","B");
    double maxsp=0, worst_theta_step=0;
    for(size_t i=1;i<path.size();++i){
      maxsp=std::max(maxsp, std::hypot(path[i].x-path[i-1].x, path[i].y-path[i-1].y));
      double dth = std::fabs(std::remainder(path[i].theta-path[i-1].theta, 2*M_PI));
      worst_theta_step=std::max(worst_theta_step, dth);
    }
    printf("seam mismatch 1e-6 -> n=%zu max_spacing=%.6f worst_heading_step=%.3f rad\n", path.size(), maxsp, worst_theta_step);
  }
  // 8. disabled edge fallback
  {
    catalog::StationCatalog c;
    catalog::Station a; a.id="A"; a.x=0; a.y=0;
    catalog::Station b; b.id="B"; b.x=3; b.y=4;
    c.stations={a,b};
    catalog::CatalogStationEdge e; e.from="A"; e.to="B"; e.distance_m=5; e.bidirectional=true; e.enabled=false;
    e.polyline={{0,0},{0,4},{3,4}};
    c.edges.push_back(e);
    SkeletonPlanner p(std::move(c));
    auto path = p.PlanBetweenNodes("A","B");
    printf("disabled edge -> PlanBetweenNodes n=%zu (expect 0)\n", path.size());
    auto path2 = p.Plan(Pose2D{0,0,0}, Pose2D{3,4,0});
    printf("disabled edge -> Plan n=%zu (expect 0)\n", path2.size());
  }
  // 9. one-point polyline edge
  {
    catalog::StationCatalog c;
    catalog::Station a; a.id="A"; a.x=0; a.y=0;
    catalog::Station b; b.id="B"; b.x=3; b.y=4;
    c.stations={a,b};
    catalog::CatalogStationEdge e; e.from="A"; e.to="B"; e.distance_m=5; e.bidirectional=true; e.enabled=true;
    e.polyline={{1,1}};
    c.edges.push_back(e);
    SkeletonPlanner p(std::move(c));
    auto path = p.PlanBetweenNodes("A","B");
    printf("1-point polyline -> n=%zu front=(%.2f,%.2f) back=(%.2f,%.2f)\n", path.size(),
           path.empty()?0:path.front().x, path.empty()?0:path.front().y,
           path.empty()?0:path.back().x, path.empty()?0:path.back().y);
  }
  return 0;
}
